-- Упражнения книги 19, глава 16 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-lv-size', 0, 'func', 'Размер тома в экстентах', 'Опция lvcreate -L принимает размер как число с необязательной единицей. Единицы на вводе всегда двоичные, регистр не важен: b — байты, s — сектора по 512 байт, k — KiB, m — MiB, g — GiB, t — TiB; без единицы число считается мебибайтами. Число может быть дробным, например 1.5g. Размер тома кратен физическому экстенту, и запрошенный размер округляется вверх до целого числа экстентов. Напишите функцию lv_extents(pe_kib, size): pe_kib — размер экстента в KiB, size — строка вроде "10G", "512k" или "1.5g". Верните кортеж (число экстентов, получившийся размер в KiB). Нулевой размер даёт (0, 0).', 'def lv_extents(pe_kib, size):
    pass
', 'Умножьте число на множитель единицы в KiB (используйте Fraction, чтобы не терять точность) и разделите на экстент с округлением вверх.', '{"func": "lv_extents", "tests": [{"args": [4096, "10G"], "expected": {"__tuple__": [2560, 10485760]}}, {"args": [4096, "10M"], "expected": {"__tuple__": [3, 12288]}}, {"args": [4096, "12"], "expected": {"__tuple__": [3, 12288]}}, {"args": [4096, "1.5g"], "expected": {"__tuple__": [384, 1572864]}}, {"args": [4096, "4096k"], "expected": {"__tuple__": [1, 4096]}}, {"args": [4096, "4097k"], "expected": {"__tuple__": [2, 8192]}}, {"args": [131072, "1G"], "expected": {"__tuple__": [8, 1048576]}}, {"args": [131072, "1m"], "expected": {"__tuple__": [1, 131072]}}, {"args": [4096, "2048s"], "expected": {"__tuple__": [1, 4096]}}, {"args": [1024, "0.5k"], "expected": {"__tuple__": [1, 1024]}}, {"args": [4096, "1T"], "expected": {"__tuple__": [262144, 1073741824]}}, {"args": [4096, "1048576b"], "expected": {"__tuple__": [1, 4096]}}, {"args": [4096, "0"], "expected": {"__tuple__": [0, 0]}}, {"args": [4096, "100M"], "expected": {"__tuple__": [25, 102400]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-percent-extents', 1, 'func', 'Проценты в -l: вниз или вверх', 'Опция -l принимает процент от VG, от свободного места группы (FREE), от свободного места перечисленных PV (PVS) или, у lvextend, от самого тома (LV). Процент считается целочисленно, число экстентов n = pct * база // 100 с таким округлением: lvcreate всегда округляет вниз; lvextend/lvreduce (cmd = "resize") округляют вверх, то есть n = (pct * база + 99) // 100, кроме знака минус, где округление вниз. База: VG — все экстенты группы vg_pe, FREE — свободные free_pe, PVS — pvs_free_pe свободных экстентов перечисленных PV, а если PV в команде не перечислены (pvs_free_pe равно None), то vg_pe; LV — lv_pe экстентов тома. Ограничения: при cmd = "create" процент от VG не больше free_pe, а база LV недопустима (верните 0); при cmd = "resize", знаке "" (абсолютный размер) и базе VG результат не больше lv_pe + free_pe. Напишите функцию percent_extents(cmd, sign, pct, base, vg_pe, free_pe, pvs_free_pe, lv_pe): cmd — "create" или "resize", sign — "", "+" или "-", base — "VG", "FREE", "PVS" или "LV", pct — целое число. Верните число экстентов.', 'def percent_extents(cmd, sign, pct, base, vg_pe, free_pe, pvs_free_pe, lv_pe):
    pass
', 'Сначала выберите базу, потом округление (up = cmd == "resize" and sign != "-"), затем применяйте два ограничения.', '{"func": "percent_extents", "tests": [{"args": ["create", "", 50, "FREE", 1000, 101, null, 0], "expected": 50}, {"args": ["resize", "+", 50, "FREE", 1000, 101, null, 40], "expected": 51}, {"args": ["create", "", 100, "VG", 1000, 300, null, 0], "expected": 300}, {"args": ["create", "", 30, "VG", 1000, 900, null, 0], "expected": 300}, {"args": ["create", "", 50, "PVS", 1000, 900, 7, 0], "expected": 3}, {"args": ["create", "", 10, "PVS", 255, 100, null, 0], "expected": 25}, {"args": ["resize", "", 80, "VG", 1000, 500, null, 100], "expected": 600}, {"args": ["resize", "-", 50, "LV", 1000, 500, null, 33], "expected": 16}, {"args": ["resize", "+", 20, "LV", 1000, 500, null, 33], "expected": 7}, {"args": ["resize", "", 50, "LV", 1000, 500, null, 33], "expected": 17}, {"args": ["create", "", 50, "LV", 1000, 500, null, 33], "expected": 0}, {"args": ["resize", "+", 100, "PVS", 1000, 20, 13, 5], "expected": 13}, {"args": ["resize", "", 100, "FREE", 10, 7, null, 3], "expected": 7}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-vg-script', 2, 'func', 'Скрипт из команд LVM на модели группы', 'Модель группы: экстент pe_kib KiB; PV размером S MiB даёт (S - 1) * 1024 // pe_kib полезных экстентов (первый MiB занят меткой и метаданными); pvs — словарь имя PV → размер в MiB. Логические тома линейные, размер тома — число экстентов, свободно всего «экстентов группы минус сумма экстентов томов». Напишите функцию run_script(pe_kib, pvs, commands): commands — список строк, команды выполняются по порядку, каждая даёт результат из списка ниже. Команды: "lvcreate -n ИМЯ -L РАЗМЕР" или "lvcreate -n ИМЯ -l СПЕЦ"; "lvextend -L РАЗМЕР ТОМ" или "lvextend -l СПЕЦ ТОМ"; "lvreduce -L РАЗМЕР ТОМ"; "lvremove ТОМ"; "vgextend ИМЯ_PV РАЗМЕР_MiB" (всегда "ok", добавляет полезные экстенты нового PV). РАЗМЕР — как в lvcreate -L: число с единицей b/s/k/m/g/t, двоичные, без единицы MiB, регистр не важен; для lvextend и lvreduce с плюсом или минусом в начале это приращение. СПЕЦ — целое число экстентов или N%FREE, N%VG (у lvextend ещё N%LV); у lvextend плюс в начале означает приращение. Округление: абсолютный размер и приращение при увеличении округляются вверх до экстента; приращение при lvreduce -L -РАЗМЕР округляется вниз (убирается не больше указанного); проценты — как в предыдущей задаче (lvcreate вниз, %VG не больше свободного; lvextend вверх, абсолютный %VG не больше текущий размер + свободное; lvreduce только -L). Результаты: "ok"; "unchanged" (новый размер равен текущему); "error: exists" (имя занято), "error: not found" (тома нет), "error: zero size" (lvcreate дал 0 экстентов или lvreduce дал размер 0 и меньше), "error: no space" (не хватает свободных экстентов), "error: not larger" (lvextend указал меньше текущего), "error: not smaller" (lvreduce указал больше текущего). Проверки идут в этом порядке: имя, затем размер, затем место. Ошибка не меняет модель. Верните кортеж (список результатов, словарь том → размер в KiB, число свободных экстентов в конце).', 'def run_script(pe_kib, pvs, commands):
    pass
', 'Храните словарь том → экстенты и пересчитывайте свободное перед каждой командой; сначала вычислите число экстентов, потом сравнивайте.', '{"func": "run_script", "tests": [{"args": [4096, {"/dev/sdb": 10240, "/dev/sdc": 10240}, ["lvcreate -n data -L 10G", "lvcreate -n logs -l 50%FREE", "lvextend -L +5G data", "lvextend -l +100%FREE logs", "lvcreate -n x -L 1M", "lvremove data", "lvcreate -n logs -l 10", "lvextend -L 8G nosuch", "lvextend -L 4G logs", "lvreduce -L -1G logs", "lvreduce -L 10G logs", "lvreduce -L -100T logs", "vgextend /dev/sdd 20481", "lvextend -L +1G logs"]], "expected": {"__tuple__": [["ok", "ok", "error: no space", "ok", "error: no space", "ok", "error: exists", "error: not found", "error: not larger", "ok", "error: not smaller", "error: zero size", "ok", "ok"], {"logs": 10477568}, 7680]}}, {"args": [131072, {"/dev/mapper/36001": 102400}, ["lvcreate -n disk1 -L 10G", "lvcreate -n disk2 -L 1M", "lvextend -L +1M disk2", "lvextend -l +50%VG disk1", "lvextend -l 50%VG disk2", "lvextend -l +10%LV disk2", "lvextend -l 90%VG disk1", "lvreduce -L -1M disk2"]], "expected": {"__tuple__": [["ok", "ok", "ok", "ok", "ok", "error: no space", "unchanged", "unchanged"], {"disk1": 62914560, "disk2": 41811968}, 0]}}, {"args": [4096, {"/dev/sdb": 1}, ["lvcreate -n a -L 4M", "vgextend /dev/sdc 9"]], "expected": {"__tuple__": [["error: no space", "ok"], {}, 2]}}, {"args": [4096, {"/dev/sdb": 101}, ["lvcreate -n a -l 100%VG", "lvcreate -n b -l 1", "lvextend -L 100M a", "lvextend -l 25 a", "lvextend -l +0 a", "lvcreate -n c -L 0", "lvreduce -L 100M a"]], "expected": {"__tuple__": [["ok", "error: no space", "unchanged", "unchanged", "unchanged", "error: zero size", "unchanged"], {"a": 102400}, 0]}}, {"args": [4096, {}, []], "expected": {"__tuple__": [[], {}, 0]}}, {"args": [512, {"/dev/vda": 3}, ["lvcreate -n tiny -L 1536k", "lvcreate -n t2 -L 1k", "lvextend -L +512k tiny", "lvreduce -L -700k tiny", "lvreduce -L -2M tiny"]], "expected": {"__tuple__": [["ok", "ok", "error: no space", "ok", "error: zero size"], {"tiny": 1024, "t2": 512}, 1]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-failure-impact', 3, 'func', 'Что потеряем, если умрёт диск', 'Дан вывод lvs -a -o lv_name,vg_name,lv_attr,lv_size,pool_lv,origin,devices (заголовки LV VG Attr LSize Pool Origin Devices). Колонки выровнены по заголовку: значение любой колонки начинается не левее первого символа её заголовка и заканчивается перед началом следующей; пустые ячейки — пробелы (колонки режьте по позициям заголовков, а не по пробелам). Функция failure_impact(text, pv) возвращает отсортированный список имён видимых томов (имена не в квадратных скобках), которые будут потеряны при отказе диска pv, например "/dev/sdb". Колонка Devices — перечень через запятую вида путь(номер экстента); учитывайте только элементы, начинающиеся с /dev/, остальные (имена томов) в расчёте не участвуют. Правила. 1) Видимый том, у которого есть экстенты на pv, потерян. 2) Скрытый том в квадратных скобках относится к родителю с именем без суффикса _tdata, _tmeta, _rimage_N, _mimage_N, _rmeta_N, _mlog или _pmspare. Экстенты скрытого тома _tdata или _tmeta на pv обрекают родителя (тонкий пул). Скрытые _rmeta_N, _mlog и _pmspare игнорируются. 3) Если у родителя есть скрытые копии _rimage_N или _mimage_N, то он потерян, только если на pv есть экстенты у каждой копии (иначе он переживает отказ, деградируя). 4) Тонкий том (первый символ Attr равен V) потерян, если потерян пул из колонки Pool. 5) Классический снимок (первый символ Attr равен s) потерян, если потерян том из колонки Origin; потеря снимка исходный том не затрагивает. Правила 4 и 5 применяются и к цепочкам зависимостей.', 'def failure_impact(text, pv):
    pass
', 'Позиции колонок возьмите из первой строки через re.finditer(r''\S+'', ...); затем сведите скрытые тома к родителям и в цикле добавляйте зависимые тома, пока набор растёт.', '{"func": "failure_impact", "tests": [{"args": ["  LV   VG  Attr       LSize  Pool Origin Devices\n  data vg0 -wi-ao---- 10.00g             /dev/sdb(0)\n  logs vg0 -wi-ao----  5.00g             /dev/sdb(2560),/dev/sdc(0)\n  web  vg0 -wi-a-----  8.00g             /dev/sdc(1280)\n", "/dev/sdb"], "expected": ["data", "logs"]}, {"args": ["  LV   VG  Attr       LSize  Pool Origin Devices\n  data vg0 -wi-ao---- 10.00g             /dev/sdb(0)\n  logs vg0 -wi-ao----  5.00g             /dev/sdb(2560),/dev/sdc(0)\n  web  vg0 -wi-a-----  8.00g             /dev/sdc(1280)\n", "/dev/sdc"], "expected": ["logs", "web"]}, {"args": ["  LV   VG  Attr       LSize  Pool Origin Devices\n  data vg0 -wi-ao---- 10.00g             /dev/sdb(0)\n  logs vg0 -wi-ao----  5.00g             /dev/sdb(2560),/dev/sdc(0)\n  web  vg0 -wi-a-----  8.00g             /dev/sdc(1280)\n", "/dev/sdd"], "expected": []}, {"args": ["  LV              VG  Attr       LSize   Pool Origin Devices\n  app             vg0 owi-aos---  10.00g             /dev/sdf(0)\n  app-snap        vg0 swi-a-s---   2.00g      app    /dev/sdg(0)\n  db              vg0 Vwi-aotz--  50.00g pool        pool(0)\n  m1              vg0 rwi-aor---  10.00g             m1_rimage_0(0),m1_rimage_1(0)\n  [m1_rimage_0]   vg0 iwi-aor---  10.00g             /dev/sdd(0)\n  [m1_rimage_1]   vg0 iwi-aor---  10.00g             /dev/sde(0)\n  [m1_rmeta_0]    vg0 ewi-aor---   4.00m             /dev/sdd(2560)\n  [m1_rmeta_1]    vg0 ewi-aor---   4.00m             /dev/sde(2560)\n  m2              vg0 rwi-aor---   1.00g             m2_rimage_0(0),m2_rimage_1(0)\n  [m2_rimage_0]   vg0 iwi-aor---   1.00g             /dev/sdh(0)\n  [m2_rimage_1]   vg0 iwi-aor---   1.00g             /dev/sdh(256)\n  [lvol0_pmspare] vg0 ewi------- 104.00m             /dev/sdc(26)\n  pool            vg0 twi-aotz-- 100.00g             pool_tdata(0)\n  [pool_tdata]    vg0 Twi-ao---- 100.00g             /dev/sdb(0)\n  [pool_tmeta]    vg0 ewi-ao---- 104.00m             /dev/sdc(0)\n  web             vg0 Vwi-aotz-- 200.00g pool        pool(0)\n  web-snap        vg0 Vwi---tz-k 200.00g pool web    pool(0)\n", "/dev/sdb"], "expected": ["db", "pool", "web", "web-snap"]}, {"args": ["  LV              VG  Attr       LSize   Pool Origin Devices\n  app             vg0 owi-aos---  10.00g             /dev/sdf(0)\n  app-snap        vg0 swi-a-s---   2.00g      app    /dev/sdg(0)\n  db              vg0 Vwi-aotz--  50.00g pool        pool(0)\n  m1              vg0 rwi-aor---  10.00g             m1_rimage_0(0),m1_rimage_1(0)\n  [m1_rimage_0]   vg0 iwi-aor---  10.00g             /dev/sdd(0)\n  [m1_rimage_1]   vg0 iwi-aor---  10.00g             /dev/sde(0)\n  [m1_rmeta_0]    vg0 ewi-aor---   4.00m             /dev/sdd(2560)\n  [m1_rmeta_1]    vg0 ewi-aor---   4.00m             /dev/sde(2560)\n  m2              vg0 rwi-aor---   1.00g             m2_rimage_0(0),m2_rimage_1(0)\n  [m2_rimage_0]   vg0 iwi-aor---   1.00g             /dev/sdh(0)\n  [m2_rimage_1]   vg0 iwi-aor---   1.00g             /dev/sdh(256)\n  [lvol0_pmspare] vg0 ewi------- 104.00m             /dev/sdc(26)\n  pool            vg0 twi-aotz-- 100.00g             pool_tdata(0)\n  [pool_tdata]    vg0 Twi-ao---- 100.00g             /dev/sdb(0)\n  [pool_tmeta]    vg0 ewi-ao---- 104.00m             /dev/sdc(0)\n  web             vg0 Vwi-aotz-- 200.00g pool        pool(0)\n  web-snap        vg0 Vwi---tz-k 200.00g pool web    pool(0)\n", "/dev/sdc"], "expected": ["db", "pool", "web", "web-snap"]}, {"args": ["  LV              VG  Attr       LSize   Pool Origin Devices\n  app             vg0 owi-aos---  10.00g             /dev/sdf(0)\n  app-snap        vg0 swi-a-s---   2.00g      app    /dev/sdg(0)\n  db              vg0 Vwi-aotz--  50.00g pool        pool(0)\n  m1              vg0 rwi-aor---  10.00g             m1_rimage_0(0),m1_rimage_1(0)\n  [m1_rimage_0]   vg0 iwi-aor---  10.00g             /dev/sdd(0)\n  [m1_rimage_1]   vg0 iwi-aor---  10.00g             /dev/sde(0)\n  [m1_rmeta_0]    vg0 ewi-aor---   4.00m             /dev/sdd(2560)\n  [m1_rmeta_1]    vg0 ewi-aor---   4.00m             /dev/sde(2560)\n  m2              vg0 rwi-aor---   1.00g             m2_rimage_0(0),m2_rimage_1(0)\n  [m2_rimage_0]   vg0 iwi-aor---   1.00g             /dev/sdh(0)\n  [m2_rimage_1]   vg0 iwi-aor---   1.00g             /dev/sdh(256)\n  [lvol0_pmspare] vg0 ewi------- 104.00m             /dev/sdc(26)\n  pool            vg0 twi-aotz-- 100.00g             pool_tdata(0)\n  [pool_tdata]    vg0 Twi-ao---- 100.00g             /dev/sdb(0)\n  [pool_tmeta]    vg0 ewi-ao---- 104.00m             /dev/sdc(0)\n  web             vg0 Vwi-aotz-- 200.00g pool        pool(0)\n  web-snap        vg0 Vwi---tz-k 200.00g pool web    pool(0)\n", "/dev/sdd"], "expected": []}, {"args": ["  LV              VG  Attr       LSize   Pool Origin Devices\n  app             vg0 owi-aos---  10.00g             /dev/sdf(0)\n  app-snap        vg0 swi-a-s---   2.00g      app    /dev/sdg(0)\n  db              vg0 Vwi-aotz--  50.00g pool        pool(0)\n  m1              vg0 rwi-aor---  10.00g             m1_rimage_0(0),m1_rimage_1(0)\n  [m1_rimage_0]   vg0 iwi-aor---  10.00g             /dev/sdd(0)\n  [m1_rimage_1]   vg0 iwi-aor---  10.00g             /dev/sde(0)\n  [m1_rmeta_0]    vg0 ewi-aor---   4.00m             /dev/sdd(2560)\n  [m1_rmeta_1]    vg0 ewi-aor---   4.00m             /dev/sde(2560)\n  m2              vg0 rwi-aor---   1.00g             m2_rimage_0(0),m2_rimage_1(0)\n  [m2_rimage_0]   vg0 iwi-aor---   1.00g             /dev/sdh(0)\n  [m2_rimage_1]   vg0 iwi-aor---   1.00g             /dev/sdh(256)\n  [lvol0_pmspare] vg0 ewi------- 104.00m             /dev/sdc(26)\n  pool            vg0 twi-aotz-- 100.00g             pool_tdata(0)\n  [pool_tdata]    vg0 Twi-ao---- 100.00g             /dev/sdb(0)\n  [pool_tmeta]    vg0 ewi-ao---- 104.00m             /dev/sdc(0)\n  web             vg0 Vwi-aotz-- 200.00g pool        pool(0)\n  web-snap        vg0 Vwi---tz-k 200.00g pool web    pool(0)\n", "/dev/sdf"], "expected": ["app", "app-snap"]}, {"args": ["  LV              VG  Attr       LSize   Pool Origin Devices\n  app             vg0 owi-aos---  10.00g             /dev/sdf(0)\n  app-snap        vg0 swi-a-s---   2.00g      app    /dev/sdg(0)\n  db              vg0 Vwi-aotz--  50.00g pool        pool(0)\n  m1              vg0 rwi-aor---  10.00g             m1_rimage_0(0),m1_rimage_1(0)\n  [m1_rimage_0]   vg0 iwi-aor---  10.00g             /dev/sdd(0)\n  [m1_rimage_1]   vg0 iwi-aor---  10.00g             /dev/sde(0)\n  [m1_rmeta_0]    vg0 ewi-aor---   4.00m             /dev/sdd(2560)\n  [m1_rmeta_1]    vg0 ewi-aor---   4.00m             /dev/sde(2560)\n  m2              vg0 rwi-aor---   1.00g             m2_rimage_0(0),m2_rimage_1(0)\n  [m2_rimage_0]   vg0 iwi-aor---   1.00g             /dev/sdh(0)\n  [m2_rimage_1]   vg0 iwi-aor---   1.00g             /dev/sdh(256)\n  [lvol0_pmspare] vg0 ewi------- 104.00m             /dev/sdc(26)\n  pool            vg0 twi-aotz-- 100.00g             pool_tdata(0)\n  [pool_tdata]    vg0 Twi-ao---- 100.00g             /dev/sdb(0)\n  [pool_tmeta]    vg0 ewi-ao---- 104.00m             /dev/sdc(0)\n  web             vg0 Vwi-aotz-- 200.00g pool        pool(0)\n  web-snap        vg0 Vwi---tz-k 200.00g pool web    pool(0)\n", "/dev/sdg"], "expected": ["app-snap"]}, {"args": ["  LV              VG  Attr       LSize   Pool Origin Devices\n  app             vg0 owi-aos---  10.00g             /dev/sdf(0)\n  app-snap        vg0 swi-a-s---   2.00g      app    /dev/sdg(0)\n  db              vg0 Vwi-aotz--  50.00g pool        pool(0)\n  m1              vg0 rwi-aor---  10.00g             m1_rimage_0(0),m1_rimage_1(0)\n  [m1_rimage_0]   vg0 iwi-aor---  10.00g             /dev/sdd(0)\n  [m1_rimage_1]   vg0 iwi-aor---  10.00g             /dev/sde(0)\n  [m1_rmeta_0]    vg0 ewi-aor---   4.00m             /dev/sdd(2560)\n  [m1_rmeta_1]    vg0 ewi-aor---   4.00m             /dev/sde(2560)\n  m2              vg0 rwi-aor---   1.00g             m2_rimage_0(0),m2_rimage_1(0)\n  [m2_rimage_0]   vg0 iwi-aor---   1.00g             /dev/sdh(0)\n  [m2_rimage_1]   vg0 iwi-aor---   1.00g             /dev/sdh(256)\n  [lvol0_pmspare] vg0 ewi------- 104.00m             /dev/sdc(26)\n  pool            vg0 twi-aotz-- 100.00g             pool_tdata(0)\n  [pool_tdata]    vg0 Twi-ao---- 100.00g             /dev/sdb(0)\n  [pool_tmeta]    vg0 ewi-ao---- 104.00m             /dev/sdc(0)\n  web             vg0 Vwi-aotz-- 200.00g pool        pool(0)\n  web-snap        vg0 Vwi---tz-k 200.00g pool web    pool(0)\n", "/dev/sdh"], "expected": ["m2"]}, {"args": ["  LV   VG  Attr       LSize  Pool Origin Devices\n  root sys -wi-ao---- 20.00g             /dev/sda2(0)\n  swap sys -wi-ao----  4.00g             /dev/sda2(5120)\n", "/dev/sda2"], "expected": ["root", "swap"]}, {"args": ["  LV   VG  Attr       LSize  Pool Origin Devices\n  root sys -wi-ao---- 20.00g             /dev/sda2(0)\n  swap sys -wi-ao----  4.00g             /dev/sda2(5120)\n", "/dev/sda"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-lvs-problems', 4, 'func', 'Проблемы в отчёте lvs --reportformat json', 'Дан вывод lvs --reportformat json -o lv_name,vg_name,lv_attr,lv_size,pool_lv,origin,data_percent,metadata_percent в виде текста: объект с ключом "report", в нём список отчётов, у каждого список "lv" объектов со строковыми значениями (проценты — строки вроде "41.20", пустая строка значит «нет значения»). Напишите функцию lvs_problems(text, limit), которая находит проблемные тома и возвращает список строк вида "vg/lv:проблема". Тома с именем в квадратных скобках пропускайте. Символы lv_attr нумеруются с 0. Проблемы: invalid — символ 4 равен I или S; merge-failed — символ 4 равен m или M; check-needed — символ 4 равен c или C; out-of-data — символ 0 равен t и символ 8 равен D; meta-readonly — символ 0 равен t и символ 8 равен M; failed — символ 8 равен F; partial — символ 8 равен p; data-high — символ 0 равен t и data_percent >= limit; meta-high — символ 0 равен t и metadata_percent >= limit; snapshot-high — символ 0 равен s и data_percent >= limit. Том может иметь несколько проблем. Результат отсортируйте по группе, затем по имени тома, затем по порядку проблем в этом перечне. Пустой отчёт даёт пустой список.', 'def lvs_problems(text, limit):
    pass
', 'json.loads, затем два вложенных цикла по report и lv; проценты переводите во float только если строка непустая.', '{"func": "lvs_problems", "tests": [{"args": ["  {\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"root\", \"vg_name\":\"sys\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"20.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"pool\", \"vg_name\":\"sys\", \"lv_attr\":\"twi-aotz--\", \"lv_size\":\"100.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"41.20\", \"metadata_percent\":\"3.10\"},\n                  {\"lv_name\":\"[pool_tdata]\", \"vg_name\":\"sys\", \"lv_attr\":\"Twi-ao----\", \"lv_size\":\"100.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"web\", \"vg_name\":\"sys\", \"lv_attr\":\"Vwi-aotz--\", \"lv_size\":\"200.00g\", \"pool_lv\":\"pool\", \"origin\":\"\", \"data_percent\":\"20.60\", \"metadata_percent\":\"\"}\n              ]\n          }\n      ]\n  }\n", 80], "expected": []}, {"args": ["  {\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"pool\", \"vg_name\":\"sys\", \"lv_attr\":\"twi-aotz--\", \"lv_size\":\"100.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"91.50\", \"metadata_percent\":\"88.00\"},\n                  {\"lv_name\":\"snap\", \"vg_name\":\"sys\", \"lv_attr\":\"swi-a-s---\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"data\", \"data_percent\":\"82.10\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"old\", \"vg_name\":\"sys\", \"lv_attr\":\"swi-I-s---\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"data\", \"data_percent\":\"100.00\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"data\", \"vg_name\":\"sys\", \"lv_attr\":\"owi-aos---\", \"lv_size\":\"10.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\"}\n              ]\n          }\n      ]\n  }\n", 80], "expected": ["sys/old:invalid", "sys/old:snapshot-high", "sys/pool:data-high", "sys/pool:meta-high", "sys/snap:snapshot-high"]}, {"args": ["  {\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"pool\", \"vg_name\":\"sys\", \"lv_attr\":\"twi-aotz--\", \"lv_size\":\"100.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"91.50\", \"metadata_percent\":\"88.00\"},\n                  {\"lv_name\":\"snap\", \"vg_name\":\"sys\", \"lv_attr\":\"swi-a-s---\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"data\", \"data_percent\":\"82.10\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"old\", \"vg_name\":\"sys\", \"lv_attr\":\"swi-I-s---\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"data\", \"data_percent\":\"100.00\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"data\", \"vg_name\":\"sys\", \"lv_attr\":\"owi-aos---\", \"lv_size\":\"10.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\"}\n              ]\n          }\n      ]\n  }\n", 95], "expected": ["sys/old:invalid", "sys/old:snapshot-high"]}, {"args": ["  {\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"pool\", \"vg_name\":\"sys\", \"lv_attr\":\"twi-aotz--\", \"lv_size\":\"100.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"91.50\", \"metadata_percent\":\"88.00\"},\n                  {\"lv_name\":\"snap\", \"vg_name\":\"sys\", \"lv_attr\":\"swi-a-s---\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"data\", \"data_percent\":\"82.10\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"old\", \"vg_name\":\"sys\", \"lv_attr\":\"swi-I-s---\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"data\", \"data_percent\":\"100.00\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"data\", \"vg_name\":\"sys\", \"lv_attr\":\"owi-aos---\", \"lv_size\":\"10.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\"}\n              ]\n          }\n      ]\n  }\n", 100], "expected": ["sys/old:invalid", "sys/old:snapshot-high"]}, {"args": ["  {\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"tp\", \"vg_name\":\"vgb\", \"lv_attr\":\"twi-aotzD-\", \"lv_size\":\"50.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"100.00\", \"metadata_percent\":\"12.00\"},\n                  {\"lv_name\":\"tm\", \"vg_name\":\"vgb\", \"lv_attr\":\"twi-aotzM-\", \"lv_size\":\"50.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"10.00\", \"metadata_percent\":\"100.00\"},\n                  {\"lv_name\":\"tf\", \"vg_name\":\"vgb\", \"lv_attr\":\"twi-a-tzF-\", \"lv_size\":\"50.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"0.00\", \"metadata_percent\":\"0.00\"},\n                  {\"lv_name\":\"tc\", \"vg_name\":\"vga\", \"lv_attr\":\"twi-cotz--\", \"lv_size\":\"50.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"55.00\", \"metadata_percent\":\"5.00\"},\n                  {\"lv_name\":\"pv\", \"vg_name\":\"vga\", \"lv_attr\":\"-wi-a---p-\", \"lv_size\":\"9.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"mg\", \"vg_name\":\"vga\", \"lv_attr\":\"Swi-aos---\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"data\", \"data_percent\":\"50.00\", \"metadata_percent\":\"\"},\n                  {\"lv_name\":\"mf\", \"vg_name\":\"vga\", \"lv_attr\":\"swi-mos---\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"data\", \"data_percent\":\"50.00\", \"metadata_percent\":\"\"}\n              ]\n          }\n      ]\n  }\n", 90], "expected": ["vga/mf:merge-failed", "vga/pv:partial", "vga/tc:check-needed", "vgb/tf:failed", "vgb/tm:meta-readonly", "vgb/tm:meta-high", "vgb/tp:out-of-data", "vgb/tp:data-high"]}, {"args": ["  {\n      \"report\": [\n          {\n              \"lv\": [\n              ]\n          }\n      ]\n  }\n", 80], "expected": []}, {"args": ["  {\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"a\", \"vg_name\":\"v1\", \"lv_attr\":\"swi-I-s---\", \"lv_size\":\"1.00g\", \"pool_lv\":\"\", \"origin\":\"x\", \"data_percent\":\"100.00\", \"metadata_percent\":\"\"}\n              ]\n          },\n          {\n              \"lv\": [\n                  {\"lv_name\":\"b\", \"vg_name\":\"v2\", \"lv_attr\":\"twi-aotz--\", \"lv_size\":\"1.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"60.00\", \"metadata_percent\":\"60.00\"}\n              ]\n          }\n      ]\n  }\n", 60], "expected": ["v1/a:invalid", "v1/a:snapshot-high", "v2/b:data-high", "v2/b:meta-high"]}, {"args": ["  {\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"a\", \"vg_name\":\"v1\", \"lv_attr\":\"swi-I-s---\", \"lv_size\":\"1.00g\", \"pool_lv\":\"\", \"origin\":\"x\", \"data_percent\":\"100.00\", \"metadata_percent\":\"\"}\n              ]\n          },\n          {\n              \"lv\": [\n                  {\"lv_name\":\"b\", \"vg_name\":\"v2\", \"lv_attr\":\"twi-aotz--\", \"lv_size\":\"1.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"60.00\", \"metadata_percent\":\"60.00\"}\n              ]\n          }\n      ]\n  }\n", 61], "expected": ["v1/a:invalid", "v1/a:snapshot-high"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-thin-timeline', 5, 'func', 'Тонкий пул: записи, trim и автоматическое расширение', 'Модель тонкого пула (всё в MiB). Пул имеет данные pool_mib; thin — словарь тонкий том → виртуальный размер. Пока ничего не записано, том занимает 0. События по порядку: ["write", том, mib] — записать mib МиБ в ещё не выделенные блоки тома: выделяется min(mib, виртуальный размер − уже выделено) и не больше свободного места пула; если выделено меньше, чем нужно, результат "full" (запись не завершилась, берётся всё, что осталось), иначе "ok"; ["trim", том, mib] — освободить не больше mib МиБ тома (результат "ok"); ["extend", mib] — увеличить пул на mib (результат "extended"). После каждого события выполняется автоматическое расширение, если порог меньше 100: когда занятое место пула строго больше порога в процентах от размера пула, пул вырастает на pool_mib * процент // 100 (один раз за событие), а результат "ok" заменяется на "autoext" ("full" и "extended" остаются). Порог меньше 50 считается равным 50; порог 100 и больше отключает автоматическое расширение. Напишите функцию thin_timeline(pool_mib, thin, events, autoext): autoext — пара [порог, процент]. Верните кортеж (размер пула в конце, занято в конце, Data% в конце, округлённый до двух знаков функцией round(занято * 100 / пул, 2), список результатов событий).', 'def thin_timeline(pool_mib, thin, events, autoext):
    pass
', 'Храните выделенное по каждому тонкому тому; занятое пула — сумма. Сравнение с порогом делайте в целых числах: used * 100 > порог * пул.', '{"func": "thin_timeline", "tests": [{"args": [100, {"a": 200, "b": 50}, [["write", "a", 60], ["write", "b", 30], ["write", "a", 20], ["trim", "a", 25], ["write", "b", 40], ["extend", 50], ["write", "a", 100]], [100, 0]], "expected": {"__tuple__": [150, 150, 100.0, ["ok", "ok", "full", "ok", "ok", "extended", "full"]]}}, {"args": [100, {"a": 200}, [["write", "a", 85], ["write", "a", 30], ["write", "a", 5]], [80, 20]], "expected": {"__tuple__": [172, 120, 69.77, ["autoext", "autoext", "autoext"]]}}, {"args": [100, {"a": 200}, [["write", "a", 55], ["write", "a", 10]], [30, 20]], "expected": {"__tuple__": [144, 65, 45.14, ["autoext", "autoext"]]}}, {"args": [100, {"a": 80, "b": 80}, [["write", "a", 100], ["write", "b", 30], ["trim", "a", 500], ["write", "b", 80]], [100, 50]], "expected": {"__tuple__": [100, 80, 80.0, ["ok", "full", "ok", "ok"]]}}, {"args": [10, {"a": 5}, [["write", "a", 5], ["write", "a", 1], ["trim", "a", 2], ["write", "a", 9]], [100, 0]], "expected": {"__tuple__": [10, 5, 50.0, ["ok", "ok", "ok", "ok"]]}}, {"args": [50, {"a": 100}, [["write", "a", 41]], [80, 0]], "expected": {"__tuple__": [50, 41, 82.0, ["autoext"]]}}, {"args": [50, {"a": 100}, [["write", "a", 40]], [80, 50]], "expected": {"__tuple__": [50, 40, 80.0, ["ok"]]}}, {"args": [64, {}, [["extend", 36]], [100, 0]], "expected": {"__tuple__": [100, 0, 0.0, ["extended"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-snapshot-timeline', 6, 'func', 'Классический снимок: заполнение и испорченность', 'Модель классического снимка (copy-on-write). Исходный том origin_mib МиБ делится на куски chunk_kib КиБ (origin_mib * 1024 делится на chunk_kib нацело); область снимка вмещает cap = snap_mib * 1024 // chunk_kib кусков, но не больше числа кусков исходного тома (больше копировать нечего). Запись [start, length] (КиБ, length > 0) затрагивает куски с номерами от start // chunk_kib до (start + length − 1) // chunk_kib, но не дальше конца исходного тома; каждый затронутый кусок при первой записи копируется в область снимка (повторная запись в тот же кусок бесплатна). Если для копирования не хватает места, копируется столько кусков по порядку номеров, сколько помещается, снимок становится испорченным на этой записи, и все следующие записи ничего не меняют. Автоматическое расширение: после каждой записи испорченность не наступила и порог меньше 100, то если заполнено строго больше порога процентов области, область вырастает на cap * процент // 100 кусков (не больше числа кусков исходного тома); порог меньше 50 считается равным 50. Напишите функцию snap_timeline(origin_mib, snap_mib, chunk_kib, writes, autoext): autoext — пара [порог, процент]. Верните кортеж (снимок ещё годен: True/False, скопировано кусков, вместимость области в кусках в конце, номер первой записи (с 0), испортившей снимок, или -1).', 'def snap_timeline(origin_mib, snap_mib, chunk_kib, writes, autoext):
    pass
', 'Храните множество уже скопированных кусков; для каждой записи отберите новые куски и сравните их число со свободным местом.', '{"func": "snap_timeline", "tests": [{"args": [16, 1, 4, [[0, 512]], [100, 0]], "expected": {"__tuple__": [true, 128, 256, -1]}}, {"args": [16, 1, 4, [[0, 512], [0, 1024], [2048, 4]], [100, 0]], "expected": {"__tuple__": [false, 256, 256, 2]}}, {"args": [16, 1, 4, [[0, 1024], [0, 4]], [100, 0]], "expected": {"__tuple__": [true, 256, 256, -1]}}, {"args": [16, 1, 4, [[2, 6], [3, 1], [4, 1]], [100, 0]], "expected": {"__tuple__": [true, 2, 256, -1]}}, {"args": [16, 1, 4, [[0, 840], [1000, 440], [4000, 4]], [80, 50]], "expected": {"__tuple__": [true, 321, 576, -1]}}, {"args": [1, 10, 4, [[0, 1024]], [100, 0]], "expected": {"__tuple__": [true, 256, 256, -1]}}, {"args": [16, 1, 4, [[0, 4]], [20, 100]], "expected": {"__tuple__": [true, 1, 256, -1]}}, {"args": [16, 1, 4, [[0, 1024], [8000, 100]], [80, 50]], "expected": {"__tuple__": [true, 281, 384, -1]}}, {"args": [16, 1, 4, [[16380, 100], [16300, 100]], [100, 0]], "expected": {"__tuple__": [true, 21, 256, -1]}}, {"args": [16, 1, 4, [], [100, 0]], "expected": {"__tuple__": [true, 0, 256, -1]}}, {"args": [64, 2, 8, [[0, 4096], [4096, 4096], [8192, 8]], [75, 100]], "expected": {"__tuple__": [false, 256, 256, 0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-evacuate-plan', 7, 'func', 'План вывода диска из группы', 'Дан вывод pvs -o pv_name,vg_name,pv_pe_count,pv_pe_alloc_count: первая строка — заголовок, дальше по строке на PV, колонки: имя PV, группа, всего экстентов, занято экстентов. У PV, не входящего ни в одну группу, ячейка группы пуста, и в строке только три поля. Напишите функцию evacuate_plan(text, pv): список команд, которыми pv выводят из его группы. Если pv нет в выводе, верните ["error: unknown PV"]; если pv не в группе — ["error: not in a VG"]; если в его группе нет других PV — ["error: last PV of the VG"]. Если на pv нет занятых экстентов, нужны две команды: "vgreduce ГРУППА PV", "pvremove PV". Иначе занятые экстенты pv переносит pvmove на свободные экстенты остальных PV той же группы (PV других групп и вне групп не считаются): если их суммарно хватает — три команды "pvmove PV", "vgreduce ГРУППА PV", "pvremove PV"; если не хватает — ["error: short by N extents"], где N — сколько экстентов не хватает.', 'def evacuate_plan(text, pv):
    pass
', 'Строки из трёх полей — PV без группы; свободное у остальных PV группы — это всего минус занято.', '{"func": "evacuate_plan", "tests": [{"args": ["  PV       VG  PE   Alloc\n  /dev/sdb vg0 2559  1280\n  /dev/sdc vg0 2559   300\n  /dev/sdd vg0 5119     0\n", "/dev/sdb"], "expected": ["pvmove /dev/sdb", "vgreduce vg0 /dev/sdb", "pvremove /dev/sdb"]}, {"args": ["  PV       VG  PE   Alloc\n  /dev/sdb vg0 2559  1280\n  /dev/sdc vg0 2559   300\n  /dev/sdd vg0 5119     0\n", "/dev/sdd"], "expected": ["vgreduce vg0 /dev/sdd", "pvremove /dev/sdd"]}, {"args": ["  PV       VG  PE   Alloc\n  /dev/sdb vg0 2559  1280\n  /dev/sdc vg0 2559   300\n  /dev/sdd vg0 5119     0\n", "/dev/sdx"], "expected": ["error: unknown PV"]}, {"args": ["  PV       VG  PE    Alloc\n  /dev/sdb vg0  2559  2000\n  /dev/sdc vg0  2559  2100\n  /dev/sdd vg1 10239     0\n  /dev/sde      2559     0\n", "/dev/sdb"], "expected": ["error: short by 1541 extents"]}, {"args": ["  PV       VG  PE    Alloc\n  /dev/sdb vg0  2559  2000\n  /dev/sdc vg0  2559  2100\n  /dev/sdd vg1 10239     0\n  /dev/sde      2559     0\n", "/dev/sdc"], "expected": ["error: short by 1541 extents"]}, {"args": ["  PV       VG  PE    Alloc\n  /dev/sdb vg0  2559  2000\n  /dev/sdc vg0  2559  2100\n  /dev/sdd vg1 10239     0\n  /dev/sde      2559     0\n", "/dev/sdd"], "expected": ["error: last PV of the VG"]}, {"args": ["  PV       VG  PE    Alloc\n  /dev/sdb vg0  2559  2000\n  /dev/sdc vg0  2559  2100\n  /dev/sdd vg1 10239     0\n  /dev/sde      2559     0\n", "/dev/sde"], "expected": ["error: not in a VG"]}, {"args": ["  PV       VG  PE   Alloc\n  /dev/sdb vg0 2559   100\n", "/dev/sdb"], "expected": ["error: last PV of the VG"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-alloc-plan', 8, 'func', 'Размещение томов по дискам: линейный, полосатый, зеркало', 'Модель размещения. free — словарь имя PV → свободные экстенты. Функция alloc_plan(free, kind, n, extents) возвращает словарь PV → сколько экстентов взять на нём (нули не включаются) либо строку с ошибкой. kind "linear": экстенты берутся с PV в алфавитном порядке имён, с каждого сколько есть, пока не наберётся extents; n игнорируется; если суммарно свободных меньше, верните "error: not enough free extents". kind "striped": n полос, число экстентов округляется вверх до кратного n, на каждую полосу приходится extents_rounded // n экстентов на отдельном PV. kind "raid1": n копий по extents экстентов, каждая на отдельном PV (служебные метаданные не учитываем). Для striped и raid1 выбирайте из PV, на которых свободно не меньше нужного на один PV количества, n штук с наибольшим свободным местом (при равенстве — по имени); если таких PV меньше n, верните "error: not enough PVs with free space".', 'def alloc_plan(free, kind, n, extents):
    pass
', 'Для striped и raid1 сначала вычислите «нужно на один PV», отфильтруйте PV и отсортируйте по (-свободно, имя).', '{"func": "alloc_plan", "tests": [{"args": [{"/dev/sdb": 100, "/dev/sdc": 50, "/dev/sdd": 300}, "linear", 0, 120], "expected": {"/dev/sdb": 100, "/dev/sdc": 20}}, {"args": [{"/dev/sdb": 100, "/dev/sdc": 50}, "linear", 0, 151], "expected": "error: not enough free extents"}, {"args": [{"/dev/sdb": 0, "/dev/sdc": 50}, "linear", 0, 50], "expected": {"/dev/sdc": 50}}, {"args": [{"/dev/sdb": 100, "/dev/sdc": 50, "/dev/sdd": 300}, "striped", 2, 101], "expected": {"/dev/sdd": 51, "/dev/sdb": 51}}, {"args": [{"/dev/sdb": 100, "/dev/sdc": 50, "/dev/sdd": 300}, "striped", 3, 150], "expected": {"/dev/sdd": 50, "/dev/sdb": 50, "/dev/sdc": 50}}, {"args": [{"/dev/sdb": 100, "/dev/sdc": 50, "/dev/sdd": 300}, "striped", 3, 151], "expected": "error: not enough PVs with free space"}, {"args": [{"/dev/sdb": 100, "/dev/sdc": 100, "/dev/sdd": 100}, "striped", 2, 10], "expected": {"/dev/sdb": 5, "/dev/sdc": 5}}, {"args": [{"/dev/sdb": 100, "/dev/sdc": 50, "/dev/sdd": 300}, "raid1", 2, 100], "expected": {"/dev/sdd": 100, "/dev/sdb": 100}}, {"args": [{"/dev/sdb": 100, "/dev/sdc": 50, "/dev/sdd": 300}, "raid1", 2, 101], "expected": "error: not enough PVs with free space"}, {"args": [{"/dev/sdb": 500}, "raid1", 2, 10], "expected": "error: not enough PVs with free space"}, {"args": [{}, "linear", 0, 1], "expected": "error: not enough free extents"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 16, 'la16-dm-name', 9, 'func', 'Имя устройства device-mapper', 'Имена в /dev/mapper собирает LVM: группа, том и необязательный служебный слой соединяются одиночным дефисом, а каждый дефис внутри имени группы или тома удваивается. Например, группа my-vg и том web-1 дают "my--vg-web--1", а слой cow у снимка snap в группе vg0 даёт "vg0-snap-cow". Напишите функцию split_dm_name(name), которая возвращает кортеж (группа, том, слой); слой — пустая строка, если его нет. Разбор идёт слева направо: пара "--" — это один дефис внутри имени, одиночный дефис — граница частей. Если частей не две и не три (например, в имени нет границы или их слишком много), верните ("", "", "").', 'def split_dm_name(name):
    pass
', 'Идите по символам: при дефисе посмотрите на следующий символ — если это тоже дефис, добавьте один дефис к текущей части и пропустите оба, иначе начните новую часть.', '{"func": "split_dm_name", "tests": [{"args": ["vg0-data"], "expected": {"__tuple__": ["vg0", "data", ""]}}, {"args": ["my--vg-web--1"], "expected": {"__tuple__": ["my-vg", "web-1", ""]}}, {"args": ["vg0-snap-cow"], "expected": {"__tuple__": ["vg0", "snap", "cow"]}}, {"args": ["vg0-pool_tdata"], "expected": {"__tuple__": ["vg0", "pool_tdata", ""]}}, {"args": ["vg0-pool-tpool"], "expected": {"__tuple__": ["vg0", "pool", "tpool"]}}, {"args": ["swap"], "expected": {"__tuple__": ["", "", ""]}}, {"args": ["a-b-c-d"], "expected": {"__tuple__": ["", "", ""]}}, {"args": ["a---b"], "expected": {"__tuple__": ["a-", "b", ""]}}, {"args": ["rhel-root"], "expected": {"__tuple__": ["rhel", "root", ""]}}, {"args": ["vg--a-lv--b-real"], "expected": {"__tuple__": ["vg-a", "lv-b", "real"]}}, {"args": [""], "expected": {"__tuple__": ["", "", ""]}}]}');
